-- GENERATED by kinoko/build.sh from model/common.lua and model/sqlite.lua.
-- Edit those files, then run kinoko/build.sh --models-only.

-- What Kinoko may do to the agent-swarm API, and what must hold while it does.
-- Reference: https://kinoko.sh/docs.md. The client scripts are in kinoko/images/swarm/k.
--
-- There is no LLM in the guest, so no real worker. The actions play the clients over
-- HTTP: an operator that creates and cancels tasks, and four workers that poll, claim,
-- write progress and finish. /k/act keeps a journal of every answer the API gave;
-- /k/audit compares that journal with what the API says now.

timing { ready_deadline_s = 600 }

-- The first boot applies every migration, and a setup step must answer within 30 s.
-- So the wait is several short steps: each returns at once when the API is up.
for n = 1, 19 do
  setup("the API boots (" .. n .. ")", "client", "/k/wait-api 25")
end
setup("the API answers", "client", "/k/wait-api 25 1")
setup("four workers register", "client", "/k/act init")
-- Every line of the search starts here: four tasks wait, agents 1 and 2 hold one each.
setup("six tasks, two of them claimed", "client", "/k/act seed")

-- The audit line, `name=number ...` (the fields: kinoko/images/swarm/k/audit).
-- One anchored match per field keeps the pattern cost small.
local FIELDS = {
  "api", "away", "hung", "tasks", "lost", "double", "redispatch", "idem", "regress", "flip", "stuck",
  "overcap", "orphan", "dupchild", "pool", "pending", "inprog", "done", "failed", "superseded", "cancelled",
}
resource("audit", {
  bash = "client",
  command = "/k/audit",
  read = function(out)
    local reading = {}
    for _, name in ipairs(FIELDS) do
      reading[name] = tonumber(string.match(out.stdout, name .. "=(%d+)")) or 0
    end
    return reading
  end,
})

-- What the search steers by: whether the API reads, how many tasks run, how many
-- crash recovery took (capped at 3) and how many wait (capped at 2).
resource("shape", {
  bash = "client",
  command = "cat /state/shape 2>/dev/null || echo boot",
  read = function(out) return out.stdout end,
  steer = true,
})

-- The workers: agents 1..n take one step each at the same time, so their polls race
-- for the same tasks. A step finishes, fails, keeps alive or abandons the task the
-- agent holds; an agent that holds none polls, and creates a task when the poll is
-- empty. `abandon` is a worker that died with a task: it never finishes it.
action("work", { bash = "client" }, function(draw, r)
  local agents = draw.int(1, 4)
  local mode = draw.pick({ "finish", "finish", "fail", "progress", "abandon" })
  return { command = "/k/act work " .. agents .. " " .. mode }
end)

-- The operator: a new pool task (the request sent once or twice at the same time,
-- under one Idempotency-Key), an old create sent again, a cancel, or a heartbeat
-- sweep at a moment of the search's choosing. One action, so that half of the
-- actions of a line are worker steps.
action("ops", { bash = "client" }, function(draw, r)
  local kind = draw.pick({ "create 1", "create 2", "replay", "cancel", "sweep" })
  local n = draw.int(1, 64)
  if kind == "replay" or kind == "cancel" then
    return { command = "/k/act " .. kind .. " " .. n }
  end
  return { command = "/k/act " .. kind }
end)

-- 1. At most one agent holds a claimed task.
always("no task is claimed by two agents", function(r) return r.audit.double == 0 end)
always("no task is dispatched twice", function(r) return r.audit.redispatch == 0 end)
always("an agent holds at most one task", function(r) return r.audit.overcap == 0 end)
always("a running task has an agent", function(r) return r.audit.orphan == 0 end)

-- 2. A task the API acknowledged is readable.
always("an acknowledged task is readable", function(r) return r.audit.lost == 0 end)
always("an Idempotency-Key names one task", function(r) return r.audit.idem == 0 end)
-- The API comes back. Kinoko judges an `eventually` check a few seconds after the
-- faults stop, before a killed API has started again, so this is a bound in guest
-- time instead: the task list is never unreadable for 40 s.
always("the API comes back after a fault", function(r) return r.audit.away <= 40 end)
-- An API that answers /health also serves requests. A fault lasts 5 s at most, so
-- 20 s of "healthy, but the task list does not read" is an API that hangs.
always("an API that answers /health serves the task list", function(r) return r.audit.hung <= 20 end)

-- 3. A terminal task stays terminal.
always("a terminal task stays terminal", function(r) return r.audit.regress == 0 end)
always("a terminal status does not change", function(r) return r.audit.flip == 0 end)

-- 4. Crash recovery: no task stays in_progress with nobody working on it. The bound
-- is 20 s without an update while the API reads (a sweep every 2 s takes a task with
-- no session after 6 s).
always("no task stays in_progress without a live agent", function(r) return r.audit.stuck == 0 end)

-- Crash recovery replaces a task it takes (a resume, or a retry after a reboot) once.
always("crash recovery makes one follow-up per task", function(r) return r.audit.dupchild == 0 end)

-- Goals: the search must reach these, or the checks above test little.
sometimes("an agent holds a task", function(r) return r.audit.inprog > 0 end)
sometimes("a task completes", function(r) return r.audit.done > 0 end)
sometimes("crash recovery takes a task from its agent", function(r) return r.audit.superseded > 0 end)

-- An answer the API gave must fit its contract. No answer at all is not a failure:
-- the API may be down or cut off.
local function no_violation(asked, answer)
  if answer == nil or answer.err ~= nil then return true end
  return string.find(answer.result.stdout, "viol=", 1, true) == nil
end
reply("work", "work: the answers fit the contract", no_violation)
reply("ops", "ops: the answer fits the contract", no_violation)

-- Variant: SQLite. What may go wrong for a while, then stops.
-- The API killed and started again (crash recovery of the WAL file):
fault { down = "app" }
-- The clients lose the API: an answer can be lost after the API did the work.
fault { cut = { "client", "app" } }

-- The database is a local file, so no fault here can make a request fail inside the
-- API. A 5xx answer is then the API's own error (for example a lock it did not wait for).
local function no_server_error(asked, answer)
  if answer == nil or answer.err ~= nil then return true end
  return string.find(answer.result.stdout, "http=5", 1, true) == nil
end
reply("work", "work: no server error on SQLite", no_server_error)
reply("ops", "ops: no server error on SQLite", no_server_error)
